import React, { useEffect, useMemo, useRef, useState } from "react";
import { Link, graphql } from "gatsby";
import { Search } from "lucide-react";
import Layout from "../components/layout/layout";
import PostCard from "../components/postCard";
import TerminalButtonLabel from "../components/terminalButtonLabel";
import { SEO as Seo } from "../components/seo";
import { searchWords, tagPath } from "../lib/content.cjs";

// Where a word matches says how relevant the article is.
const WEIGHTS = { title: 8, tags: 5, description: 3, body: 1 };
function rank(nodes, query) {
  const terms = searchWords(query);
  if (!terms.length) return nodes;
  return nodes
    .map((node) => {
      const p = node.frontmatter;
      const fields = {
        title: searchWords(p.title).join(" "),
        tags: searchWords((p.tags || []).join(" ")).join(" "),
        description: searchWords(p.description || node.excerpt).join(" "),
        body: node.fields.searchText || "",
      };
      let score = 0;
      for (const term of terms) {
        const hits = Object.keys(WEIGHTS).filter((field) => fields[field].includes(term));
        if (!hits.length) return null;
        score += Math.max(...hits.map((field) => WEIGHTS[field]));
      }
      return { node, score };
    })
    .filter(Boolean)
    .sort((a, b) => b.score - a.score)
    .map(({ node }) => node);
}

export default function SearchPage({ data, location }) {
  const [query, setQuery] = useState("");
  const [restored, setRestored] = useState(false);
  const input = useRef(null);
  // Restore the query from the address, so Back returns to the same results.
  useEffect(() => {
    setQuery(new URLSearchParams(location.search).get("q") || "");
    setRestored(true);
    if (location.state?.focusSearch) input.current?.focus();
  }, [location.search, location.state]);
  useEffect(() => {
    if (!restored) return;
    const trimmed = query.trim();
    const search = trimmed ? `?q=${encodeURIComponent(trimmed)}` : "";
    if (search !== window.location.search) {
      window.history.replaceState(window.history.state, "", search || window.location.pathname);
    }
  }, [query, restored]);
  // Search stays entirely in the browser; no queries are sent to Analytics.
  const results = useMemo(() => rank(data.allMdx.nodes, query), [data.allMdx.nodes, query]);
  const topics = [...data.allMdx.group].sort((a, b) => b.totalCount - a.totalCount).slice(0, 6);
  const searching = Boolean(query.trim());
  return (
    <Layout>
      <section className="page-intro narrow">
        <h1>Search the notebook.</h1>
        <p>Look up a topic, a tool, or something you want to build.</p>
      </section>
      <div className="search-content">
        <label className="search-label" htmlFor="article-search">
          Search articles
        </label>
        <div className="search-field">
          <Search size={22} aria-hidden="true" />
          <input
            ref={input}
            id="article-search"
            type="search"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Try dithering, CAN, or e-paper…"
            autoComplete="off"
            aria-describedby="search-hint"
          />
          <kbd className="search-key" aria-hidden="true">/</kbd>
        </div>
        <p id="search-hint" className="search-hint">
          Searches titles, topics, and the full text of every article.
          <span className="search-hint-key"> Press / to search from any page.</span>
        </p>
        <p className="search-count" role="status">
          {results.length} {results.length === 1 ? "article" : "articles"}
          {searching ? " found" : " to explore"}
        </p>
        {results.length > 0 && <PostCard nodes={results} variant="archive" />}
        {!results.length && (
          <div className="empty-state">
            <h2>No notes found yet.</h2>
            <p>Try a shorter phrase, or start from a topic:</p>
            <nav className="topic-nav" aria-label="Popular topics">
              {topics.map((topic) => (
                <Link className="topic-chip" key={topic.fieldValue} to={tagPath(topic.fieldValue)}>
                  {topic.fieldValue}
                  <span>{topic.totalCount}</span>
                </Link>
              ))}
            </nav>
            <button
              className="button secondary"
              onClick={() => {
                setQuery("");
                input.current?.focus();
              }}
            >
              <TerminalButtonLabel label="Clear search" />
            </button>
          </div>
        )}
      </div>
    </Layout>
  );
}
export const query = graphql`
  query SearchArticles {
    allMdx(sort: { frontmatter: { date: DESC } }) {
      nodes {
        ...PostCardData
        fields {
          searchText
        }
      }
      group(field: { frontmatter: { tags: SELECT } }) {
        fieldValue
        totalCount
      }
    }
  }
`;
export const Head = () => (
  <Seo title="Search articles" pathname="/search/" noindex />
);
